js_mini_tooltip_formatter &lt;- JS("
function () {
  var p = this.point;
  var chart = this.series.chart;

  // Largeur dispo (mobile-friendly)
  var vw = (Highcharts.win && Highcharts.win.innerWidth) ? Highcharts.win.innerWidth : 360;
  var cw = chart && chart.chartWidth ? chart.chartWidth : vw;

  // Tooltip width : on garde une marge, et on plafonne pour éviter un énorme tooltip sur desktop
  var w = Math.min(560, Math.floor(Math.min(vw, cw) * 0.95));
  // Hauteur du mini-chart : plus petite sur mobile
  var isMobile = vw &lt; 520;
  var h = isMobile ? 150 : 180;

  var divId = 'mini_bar_' + p.series.index + '_' + p.index;

  var html =
    '&lt;div style=\"width:' + w + 'px; max-width:95vw\"&gt;' +
      '&lt;div style=\"margin-bottom:8px\"&gt;' +
        '&lt;div style=\"font-weight:600;font-size:13px\"&gt;' + (p.name || p.id) + '&lt;/div&gt;' +
        '&lt;div style=\"opacity:.85\"&gt;Part 15–29 (département) : &lt;b&gt;' +
          Highcharts.numberFormat(p.y, 1) + ' %&lt;/b&gt;&lt;/div&gt;' +
        '&lt;div style=\"opacity:.75\"&gt;Top 3 communes&lt;/div&gt;' +
      '&lt;/div&gt;' +
      '&lt;div id=\"' + divId + '\" style=\"width:' + w + 'px; height:' + h + 'px\"&gt;&lt;/div&gt;' +
    '&lt;/div&gt;';

  // Détruire l'ancien mini-chart
  if (chart.__mini && chart.__mini.destroy) {
    chart.__mini.destroy();
    chart.__mini = null;
  }

  setTimeout(function () {
    var container = document.getElementById(divId);
    if (!container) return;

    var d = (p.custom && p.custom.detail) ? p.custom.detail : [];
    if (!d || d.length === 0) {
      container.innerHTML = '&lt;div style=\"opacity:.7\"&gt;(pas de détail)&lt;/div&gt;';
      return;
    }

    var cats = d.map(function (o) { return o.name; });
    var vals = d.map(function (o) { return o.y; });

    // Marges plus compactes sur mobile
    var maxLen = 0;
    for (var i = 0; i &lt; cats.length; i++) maxLen = Math.max(maxLen, (cats[i] || '').length);

    // marge gauche dynamique mais bornée (sinon ça explose)
    var leftMargin = Math.min(isMobile ? 160 : 260, Math.max(isMobile ? 110 : 150, 6.5 * maxLen));
    // marge droite pour que les % respirent
    var rightMargin = isMobile ? 40 : 55;

    var seriesData = vals.map(function (v) {
      var inside = v &gt;= 6;
      return {
        y: v,
        dataLabels: {
          inside: inside,
          align: 'right',
          x: inside ? -6 : 6
        }
      };
    });

    chart.__mini = Highcharts.chart(divId, {
      chart: {
        type: 'bar',
        backgroundColor: 'transparent',
        margin: [5, rightMargin, 20, leftMargin],
        spacing: [0, 0, 0, 0],
        animation: false,
        reflow: true
      },
      title: { text: null },
      credits: { enabled: false },
      exporting: { enabled: false },
      legend: { enabled: false },
      tooltip: { enabled: false },

      xAxis: {
        categories: cats,
        lineWidth: 0,
        tickLength: 0,
        labels: {
          style: { fontSize: isMobile ? '10px' : '11px' },
          formatter: function () {
            var s = this.value || '';
            var max = isMobile ? 28 : 42; // coupe plus agressive sur mobile
            return s.length &gt; max ? (s.substring(0, max - 1) + '…') : s;
          }
        }
      },

      yAxis: {
        min: 0,
        max: 30,
        gridLineWidth: 0,
        title: { text: null },
        labels: { enabled: false },
        lineWidth: 0,
        tickLength: 0
      },

      plotOptions: {
        series: {
          animation: false,
          borderWidth: 0,
          pointPadding: 0.18,
          groupPadding: 0.06,
          dataLabels: {
            enabled: true,
            crop: false,
            overflow: 'allow',
            formatter: function () {
              return Highcharts.numberFormat(this.y, 1) + ' %';
            },
            style: { fontSize: isMobile ? '10px' : '11px', textOutline: 'none' }
          }
        }
      },

      series: [{
        name: 'Top 3',
        color: '#6f8f7a',
        data: seriesData
      }]
    });
  }, 10);

  return html;
}
")
